type CacheEntry = {
  value: string;
  expiresAt: number;
};

@Controller('sync')
export class SyncController {
  private readonly etagCache = new Map<string, CacheEntry>();
  private readonly ttlMs = 5 * 60 * 1000;

  constructor(private readonly syncService: SyncService, private readonly deviceService: DeviceService) {}

  private resolveCachedEtag(deviceId: string, ifNoneMatch?: string): { matched: boolean; cachedEtag?: string } {
    if (!ifNoneMatch) {
      return { matched: false };
    }

    const cached = this.etagCache.get(deviceId);
    if (!cached) {
      return { matched: false };
    }

    if (cached.expiresAt < Date.now()) {
      this.etagCache.delete(deviceId);
      return { matched: false };
    }

    if (cached.value !== ifNoneMatch) {
      return { matched: false };
    }

    return { matched: true, cachedEtag: cached.value };
  }

  private cacheEtag(deviceId: string, etag: string): void {
    this.etagCache.set(deviceId, {
      value: etag,
      expiresAt: Date.now() + this.ttlMs,
    });
  }

  @Public()
  @Get(':deviceId')
  @UseGuards()
  @Throttle({ default: { limit: 500, ttl: 60000 } })
  async getDeviceManifest(
    @Param('deviceId') deviceId: string,
    @Headers('if-none-match') ifNoneMatch: string,
  ) {
