3|import { DeviceService } from '../device/device.service';
4|import { SyncService } from './sync.service';
5|import { Public } from '../auth/decorators/public.decorator';
6|
7|type CacheEntry = {
8|  value: string;
9|  expiresAt: number;
10|};
11|
12|@Controller('sync')
13|export class SyncController {
14|  private readonly etagCache = new Map<string, CacheEntry>();
15|  private readonly ttlMs = 5 * 60 * 1000;
16|
17|  constructor(private readonly syncService: SyncService, private readonly deviceService: DeviceService) {}
18|
19|  private resolveCachedEtag(deviceId: string, ifNoneMatch?: string): { matched: boolean; cachedEtag?: string } {
20|    if (!ifNoneMatch) {
21|      return { matched: false };
22|    }
23|
24|    const cached = this.etagCache.get(deviceId);
25|    if (!cached) {
26|      return { matched: false };
27|    }
28|
29|    if (cached.expiresAt < Date.now()) {
30|      this.etagCache.delete(deviceId);
31|      return { matched: false };
32|    }
33|
34|    if (cached.value !== ifNoneMatch) {
35|      return { matched: false };
36|    }
37|
38|    return { matched: true, cachedEtag: cached.value };
39|  }
40|
41|  private cacheEtag(deviceId: string, etag: string): void {
42|    this.etagCache.set(deviceId, {
43|      value: etag,
44|      expiresAt: Date.now() + this.ttlMs,
45|    });
46|  }
47|
48|  @Public()
49|  @Get(':deviceId')
50|  @UseGuards()
51|  @Throttle({ default: { limit: 500, ttl: 60000 } })
52|  async getDeviceManifest(
53|    @Param('deviceId') deviceId: string,
54|    @Headers('if-none-match') ifNoneMatch: string,
55|  ) {
56|    if (!deviceId) {
57|      throw new HttpException('DEVICE_ID_REQUIRED', HttpStatus.BAD_REQUEST);
58|    }
59|
60|    const cachedMatch = this.resolveCachedEtag(deviceId, ifNoneMatch);
61|    if (cachedMatch.matched && cachedMatch.cachedEtag) {
62|      return { status: HttpStatus.NOT_MODIFIED };
63|    }
64|
