{"content":"import { Controller, Get, Param, Headers, HttpException, HttpStatus } from '@nestjs/common';
import { SyncService } from './sync.service';
import { Public } from '../auth/decorators/public.decorator';

type CacheEntry = {
  value: string;
  expiresAt: number;
};

@Controller('sync')
export class SyncController {
  private readonly etagCache = new Map<string, CacheEntry>();
  private readonly ttlMs = 5 * 60 * 1000;

  constructor(private readonly syncService: SyncService) {}

  private resolveCachedEtag(deviceId: string, ifNoneMatch?: string): boolean {
    if (!ifNoneMatch) {
      return false;
    }
    const cached = this.etagCache.get(deviceId);
    if (!cached || cached.expiresAt < Date.now()) {
      if (cached) {
        this.etagCache.delete(deviceId);
      }
      return false;
    }
    return cached.value === ifNoneMatch;
  }

  private cacheEtag(deviceId: string, etag: string): void {
    this.etagCache.set(deviceId, {
      value: etag,
      expiresAt: Date.now() + this.ttlMs,
    });
  }

  /**
   * GET /sync/:deviceId — Playlist manifest + kill-switch.
   *
   * Cache ETag en memoria (Map TTL 5 min) para reducir queries a Prisma
   * cuando el tablet ya tiene el manifest actual.
   *
   * killSwitch=true → HTTP 402 PAYMENT_REQUIRED (el manifest sigue en body
   * para que el cliente pueda inspectarlo si quiere).
   */
  @Public()
  @Get(':deviceId')
  async getDeviceManifest(
    @Param('deviceId') deviceId: string,
    @Headers('if-none-match') ifNoneMatch: string,
  ) {
    if (!deviceId) {
      throw new HttpException('DEVICE_ID_REQUIRED', HttpStatus.BAD_REQUEST);
    }

    const cachedMatch = this.resolveCachedEtag(deviceId, ifNoneMatch);
    if (cachedMatch) {
      // El middleware/framework setea 304 basado en el header ETag que devolvemos,
      // aqui solo necesitamos retornar para que Nest envie el cuerpo vacio.
      // Como no temos Response de Express, usamos un estado especial.
      return { statusCode: HttpStatus.NOT_MODIFIED, body: undefined };
    }

    const manifest = await this.syncService.getDeviceManifest(deviceId);
    const killSwitch = (manifest as unknown as { killSwitch?: boolean }).killSwitch;

    if (killSwitch) {
      // 402 sin cachear ETag — el bloqueo no debe ser cacheado por el cliente.
      throw new HttpException(manifest, HttpStatus.PAYMENT_REQUIRED);
    }

    const etag = (manifest as unknown as { etag?: string }).etag || '';
    this.cacheEtag(deviceId, etag);

    return {
      statusCode: HttpStatus.OK,
      headers: {
        'ETag': etag,
        'Cache-Control': 'public, max-age=0, must-revalidate',
      },
      body: manifest,
    };
  }
